#!/usr/bin/env bash
# Generated by pivota-spec init-dev-server
# Catalog entry: agent-synthesized
# Generator version: init-dev-server@1
#
# Edits ABOVE the END PIVOTA PREAMBLE marker are reset on regen.
# Edits BELOW the marker are preserved on regen.
#
# Why these choices (decision-trace; do not delete):
#   - `set -euo pipefail` not just `-e` — RESEARCH.md Pitfall 4 (silent pipe failures).
#   - `sha256sum` for lockfile hashing — RESEARCH.md "Don't hand-roll" (universal
#     coreutils, no extra dep vs blake3 / git hash-object / md5sum).
#   - Backoff 1s / 2s / 4s — Claude's Discretion per CONTEXT.md (small base, predictable).
#   - Log destination `/tmp/pivota-dev.log` — Open Question #4 resolved (always
#     writable inside Daytona sandboxes; matches existing convention).
#   - Lockfile-sentinel skip combined with INSTALL_PRESENCE_CHECK — RESEARCH.md
#     Pitfall 6 (sentinel survives reboots but install output dirs may not on
#     fresh tmpfs; never skip on a clean directory).
#   - Agent fallback: multi-match (compose + node-express) → synthesized multi-process
#     wrapper. Stack: Postgres+Redis via docker compose infrastructure services,
#     Express/tsx backend (port 3000), React+Vite frontend in client/ (port 5173).
#   - compose infrastructure only (`db` + `redis`), NOT the app service (which
#     uses a compiled build and is unsuitable for dev iteration).
#   - Backend launched via `npm run dev` (tsx watch) — no pre-build required.
#   - Frontend launched from client/ via `npm run dev` (vite) — already sets
#     host: '0.0.0.0' in vite.config.ts.
#   - Migrate runs via `npm run migrate` after backend install, before server start.
#   - Multi-process: bash trap + background PIDs + wait -n (RESEARCH.md Pattern 3).

set -euo pipefail

# === Bash version guard (RESEARCH.md Pitfall 8) ===
# `wait -n` (used by the multi-process variant) requires bash >= 4.3.
# Fail fast with a clear message; do not silently degrade.
if (( BASH_VERSINFO[0] < 4 )) || { (( BASH_VERSINFO[0] == 4 )) && (( BASH_VERSINFO[1] < 3 )); }; then
  echo "[pivota] bash 4.3+ required for 'wait -n'; found ${BASH_VERSION}" >&2
  exit 127
fi

# === Single-instance guard ===
exec 200>/tmp/pivota-dev.lock
if ! flock -n 200; then
  echo "[pivota] start-dev.sh already running (lock held) — exiting; poll the ready port instead" >&2
  exit 0
fi

# === D-11.4: tee stdout/stderr to /tmp/pivota-dev.log AND pass through ===
mkdir -p /tmp
exec > >(tee -a /tmp/pivota-dev.log) 2>&1
echo "[pivota] $(date -Iseconds) start-dev.sh begin (catalog: agent-synthesized)"

# === D-11.1 + D-11.2: per-stack 0.0.0.0 binding + host allowlist relaxation ===
# Backend (Express): Node's server.listen(port) binds all interfaces by default.
# HOST=0.0.0.0 covers express apps that explicitly read HOST.
export HOST=0.0.0.0
export PORT="${PORT:-3000}"
# DO NOT set NODE_ENV=production — strips devDependencies (tsx, typescript),
# breaking the dev runner (runtime-environment.md §4).

# === D-11.3: .env.example -> .env seed (platform-injection-safe) ===
if [[ ! -f .env && -f .env.example ]]; then
  echo "[pivota] seeding .env from .env.example (preserving platform-injected vars)"
  while IFS= read -r line || [[ -n "$line" ]]; do
    trimmed="${line#"${line%%[![:space:]]*}"}"
    if [[ "$trimmed" == \#* || -z "$trimmed" || "$trimmed" != *"="* ]]; then
      printf '%s\n' "$line"; continue
    fi
    key="${trimmed#export }"; key="${key%%=*}"; key="${key//[[:space:]]/}"
    if [[ -n "${!key+x}" ]]; then
      printf '# [pivota] %s omitted — provided by platform environment\n' "$key"
      continue
    fi
    if [[ "$line" != *\"* && "$line" != *\'* ]]; then
      line="$(printf '%s' "$line" | sed -E 's/[[:space:]]+#.*$//')"
    fi
    value="${line#*=}"
    value_lc="$(printf '%s' "$value" | tr '[:upper:]' '[:lower:]')"
    if [[ "$value_lc" == change_me* || "$value_lc" == changeme* ]]; then
      generated="$(head -c 48 /dev/urandom | base64 | tr -dc 'A-Za-z0-9')"
      printf '%s=%s\n' "$key" "${generated:0:48}"
      echo "[pivota] generated random value for placeholder $key" >&2
    else
      printf '%s\n' "$line"
    fi
  done < .env.example > .env
fi

# === Start infrastructure services (db + redis) via docker compose ===
# Only bring up the infrastructure services — NOT the app service (which runs
# a compiled build and is not suitable for hot-reload development).
echo "[pivota] starting infrastructure services (db, redis) via docker compose"
docker compose up -d db redis
echo "[pivota] waiting for db and redis to be healthy..."
# Poll up to 60s for both services to be healthy
for i in $(seq 1 12); do
  DB_HEALTHY=$(docker compose ps --status healthy db 2>/dev/null | grep -c "db" || true)
  REDIS_HEALTHY=$(docker compose ps --status healthy redis 2>/dev/null | grep -c "redis" || true)
  if [[ "$DB_HEALTHY" -ge 1 && "$REDIS_HEALTHY" -ge 1 ]]; then
    echo "[pivota] infrastructure services healthy"
    break
  fi
  echo "[pivota] waiting for services (attempt $i/12)..."
  sleep 5
done

# === D-12: idempotent install via lockfile hash + presence check (root backend) ===
SENTINEL="/tmp/pivota-setup-sentinel"
LOCK_FILE_PATH="package-lock.json"
INSTALL_PRESENCE_CHECK="node_modules"

run_install() {
  local dir="$1"
  local cmd="$2"
  echo "[pivota] running install in ${dir}: ${cmd}"
  local rc=0
  (cd "$dir" && bash -c "$cmd") || rc=$?
  if (( rc == 0 )); then return 0; fi
  if [[ "$cmd" == *"npm "* ]]; then
    echo "[pivota] WARN install failed (exit=$rc) — retrying with --legacy-peer-deps"
    local rc2=0
    (cd "$dir" && npm install --legacy-peer-deps) || rc2=$?
    if (( rc2 == 0 )); then
      echo "[pivota] WARN install succeeded via --legacy-peer-deps fallback"
      return 0
    fi
    rc=$rc2
  fi
  echo "[pivota] FATAL install failed (exit=$rc) — dev server cannot start" >&2
  return "$rc"
}

# Install root (backend) dependencies
if [[ -n "$LOCK_FILE_PATH" && -f "$LOCK_FILE_PATH" ]]; then
  CURRENT_HASH=$(sha256sum "$LOCK_FILE_PATH" | cut -d' ' -f1)
  PREVIOUS_HASH=$(cat "${SENTINEL}-root" 2>/dev/null || echo "")
  PRESENCE_OK=1
  if [[ -n "$INSTALL_PRESENCE_CHECK" && ! -e "$INSTALL_PRESENCE_CHECK" ]]; then
    PRESENCE_OK=0
  fi
  if [[ "$CURRENT_HASH" == "$PREVIOUS_HASH" && "$PRESENCE_OK" == "1" ]]; then
    echo "[pivota] root lockfile unchanged AND node_modules present; skipping backend install"
  else
    run_install "." "npm ci --include=dev --prefer-offline 2>/dev/null || npm install --include=dev"
    echo "$CURRENT_HASH" > "${SENTINEL}-root"
  fi
else
  if [[ ! -f "${SENTINEL}-root" ]]; then
    run_install "." "npm ci --include=dev --prefer-offline 2>/dev/null || npm install --include=dev"
    touch "${SENTINEL}-root"
  fi
fi

# Install client (frontend) dependencies
CLIENT_LOCK="client/package-lock.json"
if [[ -f "$CLIENT_LOCK" ]]; then
  CLIENT_HASH=$(sha256sum "$CLIENT_LOCK" | cut -d' ' -f1)
  CLIENT_PREV=$(cat "${SENTINEL}-client" 2>/dev/null || echo "")
  CLIENT_PRESENCE_OK=1
  if [[ ! -d "client/node_modules" ]]; then CLIENT_PRESENCE_OK=0; fi
  if [[ "$CLIENT_HASH" == "$CLIENT_PREV" && "$CLIENT_PRESENCE_OK" == "1" ]]; then
    echo "[pivota] client lockfile unchanged AND node_modules present; skipping frontend install"
  else
    run_install "client" "npm ci --include=dev --prefer-offline 2>/dev/null || npm install --include=dev"
    echo "$CLIENT_HASH" > "${SENTINEL}-client"
  fi
else
  if [[ ! -f "${SENTINEL}-client" ]]; then
    run_install "client" "npm ci --include=dev --prefer-offline 2>/dev/null || npm install --include=dev"
    touch "${SENTINEL}-client"
  fi
fi

# === Migrate: run AFTER install so tsx/node_modules are available ===
# Uses the project's own migrate script. Loud but non-fatal so a transient
# hiccup (e.g. DB still warming) doesn't strand boot.
if [[ -n "${DATABASE_URL:-}" ]]; then
  echo "[pivota] running database migration: npm run migrate"
  npm run migrate || echo "[pivota] WARNING: npm run migrate returned non-zero (continuing)"
fi

# === Multi-process supervision: bash trap + background PIDs + wait -n ===
# (RESEARCH.md Pattern 3 — no concurrently/pm2/supervisord)
shutdown() {
  echo "[pivota] shutting down children"
  kill -TERM "${PIDS[@]}" 2>/dev/null || true
  sleep 2
  kill -KILL "${PIDS[@]}" 2>/dev/null || true
  wait
}
trap shutdown SIGTERM SIGINT EXIT

declare -a PIDS=()

# Process 1: Express backend (tsx watch — no pre-build required, runtime-environment.md §7)
(
  cd .
  export HOST=0.0.0.0
  export PORT="${PORT:-3000}"
  exec bash -c 'npm run dev'
) 2>&1 | sed 's/^/[backend] /' &
PIDS+=($!)

# Process 2: React+Vite frontend (client/ — vite.config.ts already sets host: '0.0.0.0')
(
  cd client
  exec bash -c 'npm run dev'
) 2>&1 | sed 's/^/[frontend] /' &
PIDS+=($!)

echo "[pivota] started backend (PID ${PIDS[0]}) and frontend (PID ${PIDS[1]})"

# Wait for any child to exit; the trap tears down siblings.
wait -n
EXIT_CODE=$?
echo "[pivota] a child process exited with code $EXIT_CODE"
shutdown
exit "$EXIT_CODE"

